package com.smartparking.gui;

import com.smartparking.model.*;
import com.smartparking.service.ParkingService;
import javax.swing.*;
import javax.swing.table.*;
import java.awt.*;
import java.awt.event.*;
import java.time.Duration;
import java.time.format.DateTimeFormatter;
import java.util.List;

public class DashboardFrame extends JFrame {
 private static final Color NAVY=new Color(20,34,57), BLUE=new Color(39,105,174), BG=new Color(244,247,251), GREEN=new Color(28,132,91), RED=new Color(186,63,69), AMBER=new Color(199,137,34);
 private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
 private final ParkingService service;
 private final JTabbedPane tabs=new JTabbedPane();
 private final JLabel[] metrics=new JLabel[6];
 private final DefaultTableModel slotsModel=model("Slot","Floor","Size","Distance (m)","Status");
 private final DefaultTableModel vehiclesModel=model("Registration","Owner","Type");
 private final DefaultTableModel activeModel=model("Ticket","Registration","Type","Slot","Entry");
 private final DefaultTableModel historyModel=model("Ticket","Registration","Type","Slot","Entry","Exit","Duration","Fee","Payment","Status");
 private final DefaultTableModel paymentModel=model("Ticket","Registration","Slot","Paid at","Method","Amount","Status");
 private final DefaultTableModel queueModel=model("Position","Registration","Vehicle","Waiting status");
 private final JTable slotsTable=new JTable(slotsModel);
 private final JTable vehiclesTable=new JTable(vehiclesModel);
 private final JTextField searchField=new JTextField(18);
 private final JTextField entryField=new JTextField(15),exitField=new JTextField(15);
 private final JComboBox<String> paymentMethod=new JComboBox<>(new String[]{"CASH","UPI","CARD"});
 private final JTextArea receipt=new JTextArea(11,44);
 private final JLabel status=new JLabel("Ready");

 public DashboardFrame(ParkingService service){this.service=service;setTitle("Smart Parking | Operations Console");setDefaultCloseOperation(EXIT_ON_CLOSE);setMinimumSize(new Dimension(1080,720));setSize(1200,800);setLocationRelativeTo(null);getContentPane().setBackground(BG);setLayout(new BorderLayout());add(header(),BorderLayout.NORTH);buildTabs();add(tabs,BorderLayout.CENTER);status.setBorder(BorderFactory.createEmptyBorder(8,16,8,16));status.setForeground(new Color(75,88,105));add(status,BorderLayout.SOUTH);refreshAll();}
 private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setBackground(NAVY);p.setBorder(BorderFactory.createEmptyBorder(17,24,17,24));JLabel title=new JLabel("SMART PARKING");title.setFont(new Font("Segoe UI",Font.BOLD,22));title.setForeground(Color.WHITE);JLabel subtitle=new JLabel("Operations dashboard  •  MySQL connected service");subtitle.setForeground(new Color(199,211,227));JPanel t=new JPanel(new GridLayout(2,1));t.setOpaque(false);t.add(title);t.add(subtitle);JButton refresh=new JButton("Refresh data");refresh.addActionListener(e->refreshAll());p.add(t,BorderLayout.WEST);p.add(refresh,BorderLayout.EAST);return p;}
 private void buildTabs(){tabs.addTab("Overview",overview());tabs.addTab("Vehicles",vehiclesPanel());tabs.addTab("Entry & Exit",parkingPanel());tabs.addTab("Parking Slots",slotsPanel());tabs.addTab("History",historyPanel());tabs.addTab("Payments",paymentsPanel());tabs.addTab("Waiting Queue",queuePanel());}
 private JPanel overview(){JPanel root=page();JPanel cards=new JPanel(new GridLayout(2,3,14,14));cards.setOpaque(false);String[] labels={"Total slots","Available","Occupied","Vehicles parked","Waiting","Total revenue"};for(int i=0;i<labels.length;i++){JPanel card=new JPanel(new BorderLayout(4,8));card.setBackground(Color.WHITE);card.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(225,231,239)),BorderFactory.createEmptyBorder(18,20,18,20)));JLabel value=new JLabel("—");value.setFont(new Font("Segoe UI",Font.BOLD,28));value.setForeground(BLUE);JLabel caption=new JLabel(labels[i]);caption.setForeground(new Color(83,99,119));card.add(value,BorderLayout.CENTER);card.add(caption,BorderLayout.SOUTH);metrics[i]=value;cards.add(card);}root.add(section("Live facility metrics",cards),BorderLayout.NORTH);JPanel lower=new JPanel(new BorderLayout(12,12));lower.setOpaque(false);lower.add(section("Currently parked",new JScrollPane(new JTable(activeModel))),BorderLayout.CENTER);JButton reg=new JButton("Register a vehicle");reg.addActionListener(e->registerDialog());lower.add(reg,BorderLayout.SOUTH);root.add(lower,BorderLayout.CENTER);return root;}
 private JPanel vehiclesPanel(){JPanel p=page();JPanel form=new JPanel(new FlowLayout(FlowLayout.LEFT,10,8));form.setBackground(Color.WHITE);JTextField reg=new JTextField(14),owner=new JTextField(16);JComboBox<String> type=new JComboBox<>(new String[]{"Car","Bike","Truck"});JButton add=new JButton("Register"),search=new JButton("Search");form.add(new JLabel("Registration"));form.add(reg);form.add(new JLabel("Owner"));form.add(owner);form.add(new JLabel("Type"));form.add(type);form.add(add);form.add(new JLabel("Find"));form.add(searchField);form.add(search);add.addActionListener(e->{try{Vehicle v=vehicle((String)type.getSelectedItem(),reg.getText(),owner.getText());service.register(v);status("Registered "+v.getRegistrationNumber());reg.setText("");owner.setText("");refreshAll();}catch(RuntimeException ex){error(ex);}});search.addActionListener(e->filterVehicles(searchField.getText()));p.add(section("Vehicle registration and lookup",form),BorderLayout.NORTH);p.add(section("Registered vehicles",new JScrollPane(vehiclesTable)),BorderLayout.CENTER);return p;}
 private JPanel parkingPanel(){JPanel p=page();JPanel body=new JPanel(new GridLayout(1,2,16,0));body.setOpaque(false);JPanel in=new JPanel(new GridBagLayout());in.setBackground(Color.WHITE);in.setBorder(BorderFactory.createEmptyBorder(22,22,22,22));GridBagConstraints g=constraints();g.gridx=0;g.gridy=0;in.add(new JLabel("Registered vehicle registration"),g);g.gridy++;in.add(entryField,g);g.gridy++;JButton enter=new JButton("Allocate nearest suitable slot");in.add(enter,g);enter.addActionListener(e->{try{ParkingTicket t=service.enter(entryField.getText());if(t==null)status("No compatible free slot. Added to persistent waiting queue.");else status("Entry confirmed · slot "+t.slot().getId()+" · ticket "+t.id());refreshAll();}catch(RuntimeException ex){error(ex);}});JPanel out=new JPanel(new GridBagLayout());out.setBackground(Color.WHITE);out.setBorder(BorderFactory.createEmptyBorder(22,22,22,22));g=constraints();g.gridx=0;g.gridy=0;out.add(new JLabel("Vehicle registration"),g);g.gridy++;out.add(exitField,g);g.gridy++;out.add(new JLabel("Payment method"),g);g.gridy++;out.add(paymentMethod,g);g.gridy++;JButton leave=new JButton("Calculate, pay and close ticket");out.add(leave,g);receipt.setEditable(false);receipt.setFont(new Font("Consolas",Font.PLAIN,13));receipt.setBackground(new Color(248,250,252));g.gridy++;out.add(new JScrollPane(receipt),g);leave.addActionListener(e->{try{ParkingTicket t=service.exit(exitField.getText(),(String)paymentMethod.getSelectedItem());receipt.setText(receiptText(t));status("Payment complete · ₹"+t.fee());refreshAll();}catch(RuntimeException ex){error(ex);}});body.add(section("Vehicle entry",in));body.add(section("Vehicle exit and receipt",out));p.add(body,BorderLayout.CENTER);return p;}
 private JPanel slotsPanel(){JPanel p=page();slotsTable.setRowHeight(30);slotsTable.setDefaultRenderer(Object.class,new javax.swing.table.DefaultTableCellRenderer(){@Override public Component getTableCellRendererComponent(JTable table,Object value,boolean selected,boolean focus,int row,int col){Component c=super.getTableCellRendererComponent(table,value,selected,focus,row,col);if(!selected&&col==4){String s=String.valueOf(value);c.setForeground(s.equals("Available")?GREEN:RED);setFont(getFont().deriveFont(Font.BOLD));}return c;}});p.add(section("Slot inventory · green available · red occupied",new JScrollPane(slotsTable)),BorderLayout.CENTER);return p;}
 private JPanel historyPanel(){JPanel p=page();p.add(section("Completed parking visits",new JScrollPane(new JTable(historyModel))),BorderLayout.CENTER);return p;}
 private JPanel paymentsPanel(){JPanel p=page();JPanel controls=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton view=new JButton("View selected receipt"),print=new JButton("Print receipt");controls.add(view);controls.add(print);JTable t=new JTable(paymentModel);view.addActionListener(e->{int row=t.getSelectedRow();if(row>=0){String id=String.valueOf(paymentModel.getValueAt(t.convertRowIndexToModel(row),0));historyModel.getRowCount();service.history().stream().filter(x->x.id().equals(id)).findFirst().ifPresent(x->receipt.setText(receiptText(x)));JOptionPane.showMessageDialog(this,new JScrollPane(receipt),"Parking receipt",JOptionPane.INFORMATION_MESSAGE);}});print.addActionListener(e->{try{receipt.print();}catch(Exception ex){error(ex);}});p.add(controls,BorderLayout.NORTH);p.add(section("Recorded payments",new JScrollPane(t)),BorderLayout.CENTER);return p;}
 private JPanel queuePanel(){JPanel p=page();p.add(section("Persistent FIFO waiting list",new JScrollPane(new JTable(queueModel))),BorderLayout.CENTER);return p;}

 private void refreshAll(){try{service.refreshFromDatabase();fill(slotsModel,service.slots().stream().map(s->new Object[]{s.getId(),s.getFloor(),s.getSize(),s.getDistance(),s.isAvailable()?"Available":"Occupied"}).toList());fill(vehiclesModel,service.vehicles().stream().sorted(java.util.Comparator.comparing(Vehicle::getRegistrationNumber)).map(v->new Object[]{v.getRegistrationNumber(),v.getOwnerName(),v.getType()}).toList());fill(activeModel,service.activeTickets().stream().map(t->new Object[]{t.id(),t.vehicle().getRegistrationNumber(),t.vehicle().getType(),t.slot().getId(),TIME.format(t.entryTime())}).toList());fill(historyModel,service.history().stream().map(t->new Object[]{t.id(),t.vehicle().getRegistrationNumber(),t.vehicle().getType(),t.slot().getId(),TIME.format(t.entryTime()),TIME.format(t.exitTime()),duration(t),t.fee(),t.paymentMethod(),t.paymentStatus()}).toList());fill(paymentModel,service.payments().stream().map(p->new Object[]{p.ticketId(),p.registrationNumber(),p.slotId(),TIME.format(p.paidAt()),p.method(),p.amount(),p.status()}).toList());List<String> waiting=service.waitingVehicles();java.util.List<Object[]> waitingRows=new java.util.ArrayList<>();for(int i=0;i<waiting.size();i++){String r=waiting.get(i);Vehicle v=service.findVehicle(r).orElse(null);waitingRows.add(new Object[]{i+1,r,v==null?"Unknown":v.getType(),"Waiting"});}fill(queueModel,waitingRows);metrics[0].setText(String.valueOf(service.slots().size()));metrics[1].setText(String.valueOf(service.availableCount()));metrics[2].setText(String.valueOf(service.slots().size()-service.availableCount()));metrics[3].setText(String.valueOf(service.activeTickets().size()));metrics[4].setText(String.valueOf(service.waitingCount()));metrics[5].setText("₹"+service.revenue());status("Data refreshed from "+(service.isPersistent()?"MySQL":"in-memory service"));}catch(RuntimeException ex){error(ex);}}
 private DefaultTableModel activeRows(){DefaultTableModel m=model("Ticket","Registration","Type","Slot","Entry");for(ParkingTicket t:service.activeTickets())m.addRow(new Object[]{t.id(),t.vehicle().getRegistrationNumber(),t.vehicle().getType(),t.slot().getId(),TIME.format(t.entryTime())});return m;}
 private void filterVehicles(String q){TableRowSorter<DefaultTableModel> sorter=new TableRowSorter<>(vehiclesModel);vehiclesTable.setRowSorter(sorter);sorter.setRowFilter(q.isBlank()?null:RowFilter.regexFilter("(?i)"+java.util.regex.Pattern.quote(q)));}
 private void registerDialog(){tabs.setSelectedIndex(1);}
 private static Vehicle vehicle(String type,String reg,String owner){return switch(type){case "Car"->new Car(reg,owner);case "Bike"->new Bike(reg,owner);default->new Truck(reg,owner);};}
 private static String duration(ParkingTicket t){long mins=Duration.between(t.entryTime(),t.exitTime()).toMinutes();return (mins/60)+"h "+(mins%60)+"m";}
 private static String receiptText(ParkingTicket t){return "SMART PARKING RECEIPT\n====================\nTicket: "+t.id()+"\nRegistration: "+t.vehicle().getRegistrationNumber()+"\nOwner: "+t.vehicle().getOwnerName()+"\nVehicle: "+t.vehicle().getType()+"\nSlot: "+t.slot().getId()+" (Floor "+t.slot().getFloor()+")\nEntry: "+TIME.format(t.entryTime())+"\nExit: "+(t.exitTime()==null?"ACTIVE":TIME.format(t.exitTime()))+"\nDuration: "+(t.exitTime()==null?"—":duration(t))+"\nHourly rate: ₹"+t.vehicle().hourlyRate()+"\nTotal: ₹"+(t.fee()==null?"—":t.fee())+"\nPayment: "+(t.paymentMethod()==null?"—":t.paymentMethod())+"\nStatus: "+(t.paymentStatus()==null?"ACTIVE":t.paymentStatus());}
 private void error(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage()==null?ex.toString():ex.getMessage(),"Operation failed",JOptionPane.ERROR_MESSAGE);status("Operation failed. Review the message and database connection.");}
 private void status(String s){status.setText(s);}
 private static DefaultTableModel model(String... columns){return new DefaultTableModel(columns,0){@Override public boolean isCellEditable(int row,int column){return false;}};}
 private static void fill(DefaultTableModel m,List<Object[]> rows){m.setRowCount(0);for(Object[] row:rows)m.addRow(row);}
 private static JPanel page(){JPanel p=new JPanel(new BorderLayout(16,16));p.setBackground(BG);p.setBorder(BorderFactory.createEmptyBorder(18,20,18,20));return p;}
 private static JPanel section(String title,Component content){JPanel p=new JPanel(new BorderLayout(8,10));p.setOpaque(false);JLabel label=new JLabel(title);label.setFont(new Font("Segoe UI",Font.BOLD,16));label.setForeground(NAVY);p.add(label,BorderLayout.NORTH);p.add(content,BorderLayout.CENTER);return p;}
 private static JPanel tablePanel(DefaultTableModel model,List<Object[]> rows){fill(model,rows);JPanel p=new JPanel(new BorderLayout());p.add(new JScrollPane(new JTable(model)));return p;}
 private static GridBagConstraints constraints(){GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(8,8,8,8);g.anchor=GridBagConstraints.WEST;g.fill=GridBagConstraints.HORIZONTAL;return g;}
}
